<template>
 <section class="qph-code-card" :aria-label="ct('短信验证')">
  <div class="qph-code-top"><span class="qph-handset" aria-hidden="true"><i></i><b>✦</b></span><div><span class="qph-eyebrow">ONE SMALL SIGNAL / YOUR OWN SPACE</span><h3>{{ct(purpose==='register'?'一个号码，接住新灵感。':purpose==='recover'?'让你的号码，带你回来。':'把号码，和你的空间连起来。')}}</h3><p>{{ct('短信只用于当前验证，验证码不会保存在浏览器里。')}}</p></div></div>
  <p v-if="policy&&!policy.deliveryReady" class="qph-unavailable" role="status">{{ct('短信服务暂未开放，已有号码仍可使用密码登录。')}}</p>
  <div v-if="policy?.deliveryReady&&policy.captchaRequired&&(remaining===0||!pending)" class="qph-captcha"><label :for="captchaInput">{{ct('图形验证码')}}</label><div><input :id="captchaInput" v-model="captchaCode" inputmode="text" autocomplete="off" maxlength="8" :disabled="disabled||busy" :placeholder="ct('先填写图形验证码')"/><button type="button" :aria-label="ct('更换图形验证码')" :disabled="busy||disabled" @click="loadCaptcha" v-html="captcha.svg||'↻'"></button></div></div>
  <div class="qph-send-row"><button class="qph-send" type="button" :disabled="!canSend" @click="send"><BrandLoader v-if="busy" :size="18"/>{{ct(busy?'正在核对申请…':remaining>0?'{seconds} 秒后可再申请':pending?'重新申请短信':'申请短信验证码',{seconds:remaining})}}<span v-if="!busy" aria-hidden="true">↗</span></button><button v-if="pending" type="button" class="qph-read" :disabled="busy||disabled" @click="readResult">{{ct('核对原申请')}}</button></div>
  <div class="qph-code-input"><label :for="codeInput">{{ct('短信验证码')}}</label><input :id="codeInput" :value="modelValue" inputmode="numeric" autocomplete="one-time-code" maxlength="6" :disabled="disabled" :placeholder="ct('六位短信数字')" @input="$emit('update:modelValue',$event.target.value.replace(/\D/g,'').slice(0,6))"/><span>{{ct(receipt?.phoneMasked?'申请号码：{phone}':'如已收到短信，可以直接填写。',{phone:receipt?.phoneMasked||''})}}</span></div>
  <p v-if="receipt&&expires>0" class="qph-small">{{ct('本次验证码约 {seconds} 秒内有效。',{seconds:expires})}}</p><p v-if="receipt&&expires===0&&!['closed','used'].includes(receipt.status)" class="qph-small">{{ct('这次申请的有效期已结束，可重新申请。')}}</p>
  <p v-if="note" class="qph-small" role="status">{{ct(note)}}</p><p v-if="error" class="qph-error" role="alert">{{ct(error)}}</p><button v-if="pending" type="button" class="qph-end" :disabled="busy||disabled" @click="reviewClose">{{ct('结束这次等待')}}</button>
  <dialog ref="closeDialog" class="qph-dialog" :aria-labelledby="endTitle" @cancel.prevent="closeDialog?.close()"><span class="qph-eyebrow">A CLEAR LITTLE STEP</span><h3 :id="endTitle">{{ct('结束这次短信等待？')}}</h3><p>{{ct('已经寄出的短信仍可能到达。结束后，这次验证码将不再使用，已完成的账户操作会保留。')}}</p><p v-if="error" class="qph-error" role="alert">{{ct(error)}}</p><footer><button type="button" @click="closeDialog?.close()">{{ct('再等等')}}</button><button type="button" class="qph-primary" :disabled="busy||disabled" @click="finishClose">{{ct('确认结束等待')}}</button></footer></dialog>
 </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,reactive,ref,useId,watch} from 'vue';
import {api} from '../../api/client.js';import {useAuth} from '../../stores/auth.js';import {currentLang} from '../../i18n/index.js';import {accountText} from '../../i18n/account-messages.js';import {newPhoneKey,normalizedPhone,phoneDeliveryReceipt,phoneProblem,phoneSeconds} from '../../lib/phone-identity.js';import {readPhonePending,savePhonePending} from '../../lib/phone-pending.js';import BrandLoader from '../design/BrandLoader.vue';import './phone-identity.css';
const props=defineProps({phone:String,modelValue:String,purpose:{type:String,required:true},policy:Object,disabled:Boolean,active:{type:Boolean,default:true},requestBase:{type:String,default:'/auth/phone/requests'}}),emit=defineEmits(['update:modelValue','receipt','busy']),auth=useAuth(),ct=(key,params)=>accountText(currentLang.value,key,params),id=useId(),endTitle='qph-end-title-'+id,captchaInput='qph-captcha-'+id,codeInput='qph-code-'+id,pending=ref(null),receipt=ref(null),busy=ref(false),error=ref(''),note=ref(''),captcha=reactive({id:'',svg:''}),captchaCode=ref(''),closeDialog=ref(null),reviewVersion=ref(0),now=ref(Date.now()),offset=ref(0);
let alive=true,epoch=0,controller,captchaController,captchaEpoch=0;const timer=setInterval(()=>{now.value=Date.now();},1000),owner=()=>auth.user?.id||'guest',stamp=()=>({owner:owner(),revision:auth.identityRevision,purpose:props.purpose,base:props.requestBase}),current=at=>alive&&props.active&&at.owner===owner()&&at.revision===auth.identityRevision&&at.purpose===props.purpose&&at.base===props.requestBase;
const remaining=computed(()=>phoneSeconds(receipt.value?.cooldownUntil,now.value,offset.value)),expires=computed(()=>phoneSeconds(receipt.value?.expiresAt,now.value,offset.value)),canSend=computed(()=>props.active&&!props.disabled&&!busy.value&&props.policy?.deliveryReady&&!!normalizedPhone(props.phone)&&remaining.value===0&&(!pending.value||receipt.value&&['submitted','failed','used','closed'].includes(receipt.value.status)));
function setBusy(value){busy.value=value;emit('busy',value);}function remember(row){pending.value=row;return savePhonePending('send',owner(),props.purpose,row);}function cancel(){epoch++;controller?.abort();controller=null;setBusy(false);closeDialog.value?.close();}
function applyReceipt(row,key){if(!phoneDeliveryReceipt(row,key,props.purpose))throw Error('短信申请结果不完整，请核对原申请。');receipt.value=row;offset.value=Date.parse(row.serverNow)-Date.now();remember({...pending.value,key,operationVersion:row.version});emit('receipt',row);if(row.status==='closed'){remember(null);emit('update:modelValue','');note.value='这次短信等待已结束，可以重新申请。';}else note.value=row.status==='submitted'?'申请已提交。若号码可用，请留意短信。':row.status==='unknown'?'发送结果尚未确认。如已收到短信，可以继续验证。':row.status==='used'?'这次验证已经使用，请核对刚才的账户处理结果。':row.status==='failed'?'这次短信未能提交，请稍后重新申请。':'申请仍在处理中，可以稍后核对。';}
async function loadCaptcha(){if(!props.active||!props.policy?.deliveryReady||!props.policy.captchaRequired)return;captchaController?.abort();const request=new AbortController(),version=++captchaEpoch,at=stamp();captchaController=request;try{const value=await api.get('/auth/captcha',{signal:request.signal,retry:false});if(!current(at)||request.signal.aborted||version!==captchaEpoch)return;captcha.id=value.captchaId;captcha.svg=value.svg;}catch(e){if(current(at)&&!request.signal.aborted&&version===captchaEpoch)error.value=e.message||'图形验证码暂未加载，请重新读取。';}}
async function readResult(){if(!pending.value||busy.value||props.disabled)return;const at=stamp(),version=++epoch,key=pending.value.key;controller=new AbortController();setBusy(true);error.value='';try{const row=await api.get(props.requestBase+'/'+key,{signal:controller.signal,retry:false});if(current(at)&&version===epoch)applyReceipt(row,key);}catch(e){if(current(at)&&version===epoch)error.value=e.status===404?'暂未找到原申请，可以稍后核对或明确结束等待。':e.message||'短信申请结果尚未确认，请稍后核对。';}finally{if(current(at)&&version===epoch)setBusy(false);}}
async function send(){if(!canSend.value)return;const problem=phoneProblem(props.phone);if(problem){error.value=problem;return;}if(props.policy.captchaRequired&&(!captcha.id||!captchaCode.value.trim())){error.value='请先填写图形验证码。';return;}const at=stamp(),version=++epoch,key=newPhoneKey(),previous=pending.value,previousReceipt=receipt.value,body={phone:normalizedPhone(props.phone),purpose:props.purpose,expectedVersion:0,...(props.policy.captchaRequired?{captchaId:captcha.id,captchaCode:captchaCode.value.trim()}:{})};controller=new AbortController();setBusy(true);error.value='';note.value='';if(!remember({key,operationVersion:0})){remember(previous);receipt.value=previousReceipt;error.value='浏览器未能保存处理编号，本次申请尚未提交。';setBusy(false);return;}receipt.value=null;emit('receipt',null);try{const row=await api.post(props.requestBase+'/'+key,body,{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;applyReceipt(row,key);emit('update:modelValue','');}catch(e){if(current(at)&&version===epoch){if([400,422,429,503].includes(e.status)){remember(previous);receipt.value=previousReceipt;}error.value=e.message||'短信申请结果尚未确认，请核对原申请。';}}finally{if(current(at)&&version===epoch){setBusy(false);captcha.id='';captchaCode.value='';if(remaining.value===0)void loadCaptcha();}}}
async function reviewClose(){if(!pending.value||busy.value||props.disabled)return;const at=stamp(),version=++epoch,key=pending.value.key;controller=new AbortController();setBusy(true);error.value='';try{let row,missing=false;try{row=await api.get(props.requestBase+'/'+key,{signal:controller.signal,retry:false});}catch(e){if(e.status!==404)throw e;missing=true;row={version:0};}if(!current(at)||version!==epoch)return;if(!missing&&!phoneDeliveryReceipt(row,key,props.purpose))throw Error('短信申请结果不完整，请核对原申请。');reviewVersion.value=row.version;await nextTick();closeDialog.value?.showModal();}catch(e){if(current(at)&&version===epoch)error.value=e.message;}finally{if(current(at)&&version===epoch)setBusy(false);}}
async function finishClose(){if(!pending.value||busy.value||props.disabled)return;const at=stamp(),version=++epoch,key=pending.value.key;controller=new AbortController();setBusy(true);error.value='';try{const row=await api.post(props.requestBase+'/'+key+'/close',{purpose:props.purpose,expectedVersion:reviewVersion.value},{signal:controller.signal,retry:false});if(!current(at)||version!==epoch)return;applyReceipt(row,key);if(!['closed','used'].includes(row.status))throw Error('这次申请已有变化，请重新核对。');if(row.status==='used'){remember(null);note.value='这次验证已经完成，结束等待不会撤销账户操作。';}closeDialog.value?.close();}catch(e){if(current(at)&&version===epoch)error.value=e.status===409?'这次申请已有变化，请重新核对。':e.message;}finally{if(current(at)&&version===epoch)setBusy(false);}}
watch([()=>props.active,()=>props.purpose,()=>props.requestBase,()=>auth.user?.id,()=>auth.identityRevision],()=>{cancel();captchaController?.abort();captchaEpoch++;captcha.id='';captcha.svg='';captchaCode.value='';receipt.value=null;emit('receipt',null);error.value='';note.value='';pending.value=props.active?readPhonePending('send',owner(),props.purpose):null;if(props.active){if(pending.value)void readResult();else void loadCaptcha();}},{immediate:true});
watch([()=>props.policy?.deliveryReady,()=>props.policy?.captchaRequired,remaining],()=>{if(props.active&&remaining.value===0&&!captcha.id)void loadCaptcha();});watch(()=>normalizedPhone(props.phone),(value,previous)=>{if(value!==previous)emit('update:modelValue','');});
onBeforeUnmount(()=>{alive=false;cancel();captchaController?.abort();clearInterval(timer);});
</script>
